def c_M_i_h_max(t, h_dev, c_M_i_min, l_M_i):
    return idleSlope * (sum(c_M_j_h_min - l_M_i_max for M_j, c_M_j_min, l_M_j_max in [(M_i, c_M_i_min, l_M_i_max) for M_i, c_M_i_min, l_M_i_max in [(M_i, c_M_i_min, l_M_i_max) for M_i in range(8)]]) / (sum(idleSlope * (c_M_j_h_max - l_M_i_max) for M_j, c_M_j_max, l_M_j_max in [(M_i, c_M_i_max, l_M_i_max) for M_i, c_M_i_max, l_M_i_max in [(M_i, c_M_i_max, l_M_i_max) for M_i in range(8)]])))

# Credit lower bound for class M_i at port h
def c_M_i_h_min(t, h_dev, c_M_i_min):
    return sendSlope * l_M_i_max / c_M_i_min

# CBS service curve (rate-latency form) for class M_i at port h
def beta_M_i_h(t, h_dev, c_M_i):
    return idleSlope * (t - c_M_i_max / idleSlope) ** + (t - c_M_i_max / idleSlope)

# WCD calculation
def wcd(t, h_dev, alpha_M_i_h, c_M_i_h_min, c_M_i_h_max):
    return alpha_M_i_h(t) + Propagation_delay + Switching_delay + Time_synchronization_error

